"""Regenerate the frozen Python casefold compatibility table, without OS I/O."""

import unicodedata
from pathlib import Path


def main():
    if unicodedata.unidata_version != "11.0.0":
        raise RuntimeError("Use the baseline Python 3.7 Unicode 11.0.0 environment")
    entries = []
    for code in range(0x110000):
        if 0xD800 <= code <= 0xDFFF:
            continue
        value = chr(code)
        folded = value.casefold()
        if folded != value:
            encoded = "".join("\\u{{{:x}}}".format(ord(c)) for c in folded)
            entries.append('    (0x{:x}, "{}"),'.format(code, encoded))
    text = (
        "// Generated by tests/fixtures/rust-port/generate-unicode-casefold.py.\n"
        "// Frozen Python 3.7 Unicode 11.0.0 casefold contract. Do not edit the table.\n"
        "pub(crate) fn casefold(value: &str) -> String {\n"
        "    let mut output = String::with_capacity(value.len());\n"
        "    for character in value.chars() {\n"
        "        match FOLDS.binary_search_by_key(&(character as u32), |(code, _)| *code) {\n"
        "            Ok(index) => output.push_str(FOLDS[index].1),\n"
        "            Err(_) => output.push(character),\n"
        "        }\n"
        "    }\n"
        "    output\n"
        "}\n"
        "const FOLDS: &[(u32, &str)] = &[\n" + "\n".join(entries) + "\n];\n"
    )
    root = Path(__file__).resolve().parents[3]
    (root / "src/common/unicode_casefold.rs").write_text(text, encoding="utf-8")
    print("Generated {} Unicode 11 casefold entries".format(len(entries)))


if __name__ == "__main__":
    main()
